import React from 'react';
import ComicCard from '../components/ComicCard';

const comics = [
  { id: 1, title: 'The Brave Hero', genre: 'Action', image: 'https://via.placeholder.com/300x450', description: 'An epic adventure of a hero fighting for justice.' },
  { id: 2, title: 'Galaxy Tales', genre: 'Sci-Fi', image: 'https://via.placeholder.com/300x450', description: 'A thrilling journey through the stars, where space adventures never end.' },
  { id: 3, title: 'The Lost City', genre: 'Adventure', image: 'https://via.placeholder.com/300x450', description: 'A group of explorers uncover the mysteries of a hidden city.' },
  { id: 4, title: 'Mystery Mansion', genre: 'Mystery', image: 'https://via.placeholder.com/300x450', description: 'Unravel the secrets hidden within an old mansion.' },
  { id: 5, title: 'Dragon Slayer', genre: 'Fantasy', image: 'https://via.placeholder.com/300x450', description: 'A brave knight sets out to defeat a terrifying dragon.' }
];

function Comics() {
  return (
    <div className="container mt-5">
      <h2 className="text-center mb-4 text-primary">All Comics</h2>
      <div className="row">
        {comics.map(comic => (
          <ComicCard key={comic.id} comic={comic} />
        ))}
      </div>
    </div>
  );
}

export default Comics;
